data class DayEntry(val d:Long,val start:Boolean=false,val end:Boolean=false,val mood:String="",val note:String="",val pain:Int=0,val spotting:Boolean=false){val date:LocalDate get()=LocalDate.ofEpochDay(d); fun empty()=!start&&!end&&mood.isBlank()&&note.isBlank()&&pain==0&&!spotting}
data class Stats(val avgCycle:Int?,val avgPeriod:Int?,val lengths:List<Int>,val next:LocalDate?,val ovulation:LocalDate?,val fertileStart:LocalDate?,val fertileEnd:LocalDate?,val regularity:String,val deviation:Double?)
data class UiState(val entries:List<DayEntry> = emptyList(),val stats:Stats=calc(emptyList()),val reminder:Boolean=true,val reminderDays:Int=2)
data class Interval(val start:LocalDate,val end:LocalDate)

private class Store(ctx:Context){
    private val p=ctx.getSharedPreferences("dongu_data",Context.MODE_PRIVATE)
    fun load():List<DayEntry>{val raw=p.getString("entries","[]")?:"[]";return runCatching{val a=JSONArray(raw);buildList{for(i in 0 until a.length()){val o=a.getJSONObject(i);add(DayEntry(o.getLong("d"),o.optBoolean("s"),o.optBoolean("e"),o.optString("m"),o.optString("n"),o.optInt("p").coerceIn(0,5),o.optBoolean("sp")))}}.sortedBy{it.d}}.getOrDefault(emptyList())}
    fun save(xs:List<DayEntry>){val a=JSONArray();xs.sortedBy{it.d}.forEach{x->a.put(JSONObject().put("d",x.d).put("s",x.start).put("e",x.end).put("m",x.mood).put("n",x.note).put("p",x.pain).put("sp",x.spotting))};p.edit().putString("entries",a.toString()).apply()}
    fun reminder()=p.getBoolean("reminder",true); fun days()=p.getInt("reminder_days",2).coerceIn(0,7)
    fun saveReminder(on:Boolean,days:Int){p.edit().putBoolean("reminder",on).putInt("reminder_days",days.coerceIn(0,7)).apply()}
}

class CycleVm(app:Application):AndroidViewModel(app){
    private val store=Store(app); private val _s=MutableStateFlow(UiState(entries=store.load(),reminder=store.reminder(),reminderDays=store.days()));val s:StateFlow<UiState> = _s.asStateFlow()
    init{refresh(_s.value.entries)}
    private fun refresh(xs:List<DayEntry>){val st=calc(xs);_s.value=_s.value.copy(entries=xs.sortedBy{it.d},stats=st);if(_s.value.reminder)Reminder.schedule(getApplication(),st.next,_s.value.reminderDays)else Reminder.cancel(getApplication())}
    private fun mutate(date:LocalDate,f:(DayEntry)->DayEntry){val xs=_s.value.entries.toMutableList();val i=xs.indexOfFirst{it.d==date.toEpochDay()};val old=if(i>=0)xs[i]else DayEntry(date.toEpochDay());val n=f(old);if(n.empty()){if(i>=0)xs.removeAt(i)}else if(i>=0)xs[i]=n else xs.add(n);store.save(xs);refresh(xs)}
    fun toggleStart(d:LocalDate)=mutate(d){it.copy(start=!it.start)};fun toggleEnd(d:LocalDate)=mutate(d){it.copy(end=!it.end)}
    fun saveDay(d:LocalDate,m:String,n:String,p:Int,sp:Boolean)=mutate(d){it.copy(mood=m,note=n.trim(),pain=p.coerceIn(0,5),spotting=sp)}
    fun reminder(on:Boolean){_s.value=_s.value.copy(reminder=on);store.saveReminder(on,_s.value.reminderDays);refresh(_s.value.entries)}
    fun reminderDays(v:Int){_s.value=_s.value.copy(reminderDays=v.coerceIn(0,7));store.saveReminder(_s.value.reminder,_s.value.reminderDays);refresh(_s.value.entries)}
}

class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);channel(this);setContent{MaterialTheme(colorScheme=colors){val ask=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){};App(onAsk={if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)ask.launch(Manifest.permission.POST_NOTIFICATIONS)})}}}}

private fun channel(c:Context){if(Build.VERSION.SDK_INT>=26){c.getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel("dongu_reminders","Döngü hatırlatmaları",NotificationManager.IMPORTANCE_DEFAULT))}}
object Reminder{private const val RC=4401;fun schedule(c:Context,next:LocalDate?,days:Int){cancel(c);if(next==null)return;val z=next.minusDays(days.toLong()).atTime(9,0).atZone(ZoneId.systemDefault());if(!z.isAfter(ZonedDateTime.now()))return;val i=Intent(c,PeriodReminderReceiver::class.java).putExtra("days",days);val pi=PendingIntent.getBroadcast(c,RC,i,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);(c.getSystemService(Context.ALARM_SERVICE) as AlarmManager).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,z.toInstant().toEpochMilli(),pi)};fun cancel(c:Context){val pi=PendingIntent.getBroadcast(c,RC,Intent(c,PeriodReminderReceiver::class.java),PendingIntent.FLAG_NO_CREATE or PendingIntent.FLAG_IMMUTABLE)?:return;(c.getSystemService(Context.ALARM_SERVICE) as AlarmManager).cancel(pi);pi.cancel()}}
class PeriodReminderReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){channel(c);val d=i.getIntExtra("days",0);val txt=when(d){0->"Tahmine göre regl bugün başlayabilir.";1->"Tahmine göre regl yarın başlayabilir.";else->"Tahmine göre regle yaklaşık $d gün kaldı."};val open=PendingIntent.getActivity(c,4402,Intent(c,MainActivity::class.java),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val n=NotificationCompat.Builder(c,"dongu_reminders").setSmallIcon(R.drawable.ic_stat_drop).setContentTitle("Döngü").setContentText(txt).setContentIntent(open).setAutoCancel(true).build();if(Build.VERSION.SDK_INT<33||ContextCompat.checkSelfPermission(c,Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)NotificationManagerCompat.from(c).notify(4403,n)}}
class BootReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){if(i.action!=Intent.ACTION_BOOT_COMPLETED)return;val st=Store(c);if(st.reminder())Reminder.schedule(c,calc(st.load()).next,st.days())}}

