@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun App(vm:CycleVm= viewModel(),onAsk:()->Unit){val s by vm.s.collectAsState();var tab by remember{mutableStateOf(Tab.CAL)};var day by remember{mutableStateOf<LocalDate?>(null)};Scaffold(containerColor=Bg,bottomBar={NavigationBar(containerColor=CardBg){NavigationBarItem(tab==Tab.CAL,{tab=Tab.CAL},{Icon(Icons.Default.CalendarMonth,null)},{Text("Takvim")});NavigationBarItem(tab==Tab.STATS,{tab=Tab.STATS},{Icon(Icons.Default.BarChart,null)},{Text("Analiz")});NavigationBarItem(tab==Tab.SETTINGS,{tab=Tab.SETTINGS},{Icon(Icons.Default.Settings,null)},{Text("Ayarlar")})}}){pad->when(tab){Tab.CAL->CalendarScreen(s,Modifier.padding(pad),{day=it},{vm.toggleStart(LocalDate.now())});Tab.STATS->StatsScreen(s,Modifier.padding(pad));Tab.SETTINGS->SettingsScreen(s,Modifier.padding(pad),{vm.reminder(it);if(it)onAsk()},{vm.reminderDays(it)})}};day?.let{d->DaySheet(d,s.entries.firstOrNull{it.d==d.toEpochDay()},{day=null},{vm.toggleStart(d)},{vm.toggleEnd(d)}){m,n,p,sp->vm.saveDay(d,m,n,p,sp);day=null}}}

@Composable private fun CalendarScreen(s:UiState,mod:Modifier,onDate:(LocalDate)->Unit,onQuick:()->Unit){var month by remember{mutableStateOf(YearMonth.now())};val today=LocalDate.now();val todayStart=s.entries.any{it.d==today.toEpochDay()&&it.start};LazyColumn(mod.fillMaxSize().statusBarsPadding(),contentPadding=PaddingValues(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("Döngü",fontSize=30.sp,fontWeight=FontWeight.Bold);Text(headline(s.stats),color=Text2,fontSize=13.sp)};item{Surface(color=if(todayStart)Soft else Pink,contentColor=if(todayStart)Color.White else Color(0xFF321421),shape=RoundedCornerShape(24.dp),modifier=Modifier.fillMaxWidth().clickable{onQuick()}){Row(Modifier.padding(18.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.WaterDrop,null);Spacer(Modifier.width(12.dp));Column{Text(if(todayStart)"Bugünkü başlangıç kaydedildi" else "Bugün regl başladı",fontWeight=FontWeight.Bold);Text(if(todayStart)"Geri almak için dokun" else "Tek dokunuşla başlangıcı işaretle",fontSize=12.sp)}}}};item{Card(colors=CardDefaults.cardColors(containerColor=CardBg),shape=RoundedCornerShape(28.dp)){Column(Modifier.padding(12.dp)){MonthHeader(month,{month=month.minusMonths(1)},{month=month.plusMonths(1)});WeekHeader();MonthGrid(month,today,s,onDate);Legend()}}};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){Metric("Ort. döngü",s.stats.avgCycle?.let{"$it gün"}?:"—",Modifier.weight(1f));Metric("Ort. regl",s.stats.avgPeriod?.let{"$it gün"}?:"—",Modifier.weight(1f));Metric("Düzen",s.stats.regularity,Modifier.weight(1f))}}}}
@Composable private fun MonthHeader(m:YearMonth,prev:()->Unit,next:()->Unit){val tr=Locale("tr","TR");val name=m.month.getDisplayName(TextStyle.FULL,tr).replaceFirstChar{it.titlecase(tr)};Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){IconButton(prev){Icon(Icons.Default.ChevronLeft,null)};Text("$name ${m.year}",Modifier.weight(1f),textAlign=TextAlign.Center,fontSize=18.sp,fontWeight=FontWeight.SemiBold);IconButton(next){Icon(Icons.Default.ChevronRight,null)}}}
@Composable private fun WeekHeader(){Row(Modifier.fillMaxWidth()){listOf("Pzt","Sal","Çar","Per","Cum","Cmt","Paz").forEach{Text(it,Modifier.weight(1f).padding(vertical=6.dp),textAlign=TextAlign.Center,fontSize=10.sp,color=Text2)}}}
@Composable private fun MonthGrid(m:YearMonth,today:LocalDate,s:UiState,onDate:(LocalDate)->Unit){val off=m.atDay(1).dayOfWeek.value-1;val map=s.entries.associateBy{it.d};val ints=intervals(s.entries);Column{repeat(6){r->Row(Modifier.fillMaxWidth()){repeat(7){c->val n=r*7+c-off+1;if(n !in 1..m.lengthOfMonth())Spacer(Modifier.weight(1f).height(62.dp))else{val d=m.atDay(n);val e=map[d.toEpochDay()];val actual=ints.any{!d.isBefore(it.start)&&!d.isAfter(it.end)};val pred=isPred(d,s.stats);val fertile=s.stats.fertileStart!=null&&s.stats.fertileEnd!=null&&!d.isBefore(s.stats.fertileStart)&&!d.isAfter(s.stats.fertileEnd);Cell(d,e,d==today,actual,pred,fertile,d==s.stats.ovulation,Modifier.weight(1f)){onDate(d)}}}}}}}
@Composable private fun Cell(d:LocalDate,e:DayEntry?,today:Boolean,actual:Boolean,pred:Boolean,fertile:Boolean,ovu:Boolean,mod:Modifier,onClick:()->Unit){val bg=when{actual->PinkStrong.copy(.85f);pred->Pink.copy(.18f);fertile->Lavender.copy(.10f);else->Color.Transparent};val border=when{today->Color.White.copy(.7f);pred->Pink.copy(.6f);fertile->Lavender.copy(.4f);else->Color.Transparent};Box(mod.height(62.dp).padding(2.dp).clip(RoundedCornerShape(15.dp)).background(bg).border(1.dp,border,RoundedCornerShape(15.dp)).clickable{onClick()}){if(!e?.note.isNullOrBlank())Box(Modifier.align(Alignment.TopEnd).padding(7.dp).size(5.dp).background(Pink,CircleShape));Column(Modifier.align(Alignment.Center),horizontalAlignment=Alignment.CenterHorizontally){Text(d.dayOfMonth.toString(),fontSize=13.sp,fontWeight=if(today||e?.start==true)FontWeight.Bold else FontWeight.Medium,color=if(actual)Color(0xFF321421)else Color.White);Spacer(Modifier.height(3.dp));when{!e?.mood.isNullOrBlank()->Text(e!!.mood,fontSize=15.sp);ovu->Box(Modifier.size(6.dp).background(Lavender,CircleShape));else->Spacer(Modifier.height(16.dp))}}}}
