r.padding(top=12.dp)){Row{Text("Ağrı düzeyi",Modifier.weight(1f));Text("$pain / 5",color=Pink,fontWeight=FontWeight.Bold)};Slider(pain.toFloat(),{pain=it.roundToInt()},valueRange=0f..5f,steps=4);FilterChip(spotting,{spotting=!spotting},{Text("Lekelenme")})}};Spacer(Modifier.height(22.dp));Button({save(mood,note,pain,spotting)},Modifier.fillMaxWidth().height(52.dp),shape=RoundedCornerShape(18.dp)){Text("Kaydet",fontWeight=FontWeight.Bold)};Spacer(Modifier.height(20.dp))}}}
