@Composable private fun Chart(v:List<Int>){val lo=v.minOrNull()?:0;val hi=v.maxOrNull()?:1;val range=(hi-lo).coerceAtLeast(1);Canvas(Modifier.fillMaxWidth().height(145.dp).background(Soft,RoundedCornerShape(18.dp)).padding(14.dp)){val step=if(v.size==1)0f else size.width/(v.size-1);val pts=v.mapIndexed{i,x->Offset(if(v.size==1)size.width/2 else i*step,size.height-(((x-lo).toFloat()/range)*size.height*.72f+size.height*.14f))};for(i in 0 until pts.lastIndex)drawLine(Pink,pts[i],pts[i+1],5f,cap=StrokeCap.Round);pts.forEach{drawCircle(Pink,7f,it);drawCircle(Soft,3f,it)}};Row(Modifier.fillMaxWidth().padding(top=6.dp),horizontalArrangement=Arrangement.SpaceBetween){v.forEach{Text("$it",fontSize=10.sp,color=Text2)}}}
@Composable private fun HistoryRow(a:LocalDate,b:LocalDate?){Card(colors=CardDefaults.cardColors(containerColor=CardBg),shape=RoundedCornerShape(20.dp)){Row(Modifier.fillMaxWidth().padding(15.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.WaterDrop,null,tint=Pink);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(shortDate(a),fontWeight=FontWeight.SemiBold);Text(if(b!=null)"Bitiş: ${shortDate(b)}" else "Bitiş kaydı yok",color=Text2,fontSize=12.sp)};if(b!=null)Text("${ChronoUnit.DAYS.between(a,b)+1} gün",color=Pink,fontWeight=FontWeight.Bold)}}}

@Composable private fun SettingsScreen(s:UiState,mod:Modifier,onRem:(Boolean)->Unit,onDays:(Int)->Unit){Column(mod.fillMaxSize().statusBarsPadding().verticalScroll(rememberScrollState()).padding(18.dp)){Text("Ayarlar",fontSize=30.sp,fontWeight=FontWeight.Bold);Text("Sade, yerel ve özel.",color=Text2,fontSize=12.sp);Spacer(Modifier.height(18.dp));Card(colors=CardDefaults.cardColors(containerColor=CardBg),shape=RoundedCornerShape(24.dp)){Column(Modifier.padding(18.dp)){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Notifications,null,tint=Pink);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text("Regl hatırlatıcısı",fontWeight=FontWeight.Bold);Text("Tahmini tarihten önce bildirim",color=Text2,fontSize=12.sp)};Switch(s.reminder,onRem)};AnimatedVisibility(s.reminder){Column(Modifier.padding(top=14.dp)){Row{Text("Kaç gün önce?",Modifier.weight(1f));Text(if(s.reminderDays==0)"Aynı gün" else "${s.reminderDays} gün",color=Pink,fontWeight=FontWeight.Bold)};Slider(s.reminderDays.toFloat(),{onDays(it.roundToInt())},valueRange=0f..7f,steps=6)}}}};Spacer(Modifier.height(13.dp));Info("Gizlilik","Tüm kayıtlar yalnızca bu cihazda tutulur. Uygulama hesap, internet veya bulut bağlantısı istemez.");Spacer(Modifier.height(13.dp));Info("Tahminler hakkında","Regl, ovülasyon ve doğurganlık tarihleri geçmiş kayıtların ortalamasına dayalı yaklaşık tahminlerdir. Tıbbi değerlendirme veya doğum kontrol yöntemi olarak kullanılmamalıdır.");Spacer(Modifier.height(18.dp));Text("Döngü 1.0.0",color=Text2,fontSize=11.sp,modifier=Modifier.align(Alignment.CenterHorizontally))}}
@Composable private fun Info(t:String,b:String){Card(colors=CardDefaults.cardColors(containerColor=CardBg),shape=RoundedCornerShape(24.dp)){Column(Modifier.padding(18.dp)){Text(t,fontWeight=FontWeight.Bold);Text(b,color=Text2,fontSize=13.sp,lineHeight=19.sp,modifier=Modifier.padding(top=7.dp))}}}

private fun calc(xs:List<DayEntry>):Stats{val starts=xs.filter{it.start}.map{it.date}.distinct().sorted();val lens=starts.zipWithNext{a,b->ChronoUnit.DAYS.between(a,b).toInt()}.filter{it>0};val durations=durations(xs);val ac=lens.takeIf{it.isNotEmpty()}?.average()?.roundToInt();val ap=durations.takeIf{it.isNotEmpty()}?.average()?.roundToInt();val dev=if(lens.size>=2){val av=lens.average();sqrt(lens.sumOf{(it-av)*(it-av)}/lens.size)}else null;val reg=when{lens.size<2->"Veri bekleniyor";dev!!<=2->"Düzenli";dev<=5->"Değişken";else->"Düzensiz"};val cycle=ac?:28;var next=starts.lastOrNull()?.plusDays(cycle.toLong());while(next!=null&&!next.isAfter(LocalDate.now()))next=next.plusDays(cycle.toLong());val ovu=next?.minusDays(14);return Stats(ac,ap,lens,next,ovu,ovu?.minusDays(5),ovu?.plusDays(1),reg,dev)}
private fun durations(xs:List<DayEntry>):List<Int>{val s=xs.filter{it.start}.map{it.date}.distinct().sorted();val e=xs.filter{it.end}.map{it.date}.distinct().sorted();return s.mapIndexedNotNull{i,a->val n=s.getOrNull(i+1);e.firstOrNull{!it.isBefore(a)&&(n==null||it.isBefore(n))}?.let{ChronoUnit.DAYS.between(a,it).toInt()+1}?.takeIf{it in 1..15}}}
private fun intervals(xs:List<DayEntry>):List<Interval>{val s=xs.filter{it.start}.map{it.date}.distinct().sorted();val e=xs.filter{it.end}.map{it.date}.distinct().sorted();val now=LocalDate.now();return s.mapIndexed{i,a->val n=s.getOrNull(i+1);val real=e.firstOrNull{!it.isBefore(a)&&(n==null||it.isBefore(n))};val end=real?:when{a.isAfter(now)->a;ChronoUnit.DAYS.between(a,now)<=9->now;else->a.plusDays(4)};Interval(a,end)}}
private fun history(xs:List<DayEntry>):List<Pair<LocalDate,LocalDate?>>{val s=xs.filter{it.start}.map{it.date}.distinct().sorted();val e=xs.filter{it.end}.map{it.date}.distinct().sorted();return s.mapIndexed{i,a->val n=s.getOrNull(i+1);a to e.firstOrNull{!it.isBefore(a)&&(n==null||it.isBefore(n))}}.reversed()}
private fun isPred(d:LocalDate,s:Stats):Boolean{val a=s.next?:return false;val b=a.plusDays(((s.avgPeriod?:5)-1).toLong());return !d.isBefore(a)&&!d.isAfter(b)}
private fun headline(s:Stats):String{val n=s.next?:return "İlk başlangıç kaydını ekleyerek tahminleri başlat.";val d=ChronoUnit.DAYS.between(LocalDate.now(),n).toInt();return when(d){0->"Tahmine göre regl bugün başlayabilir.";1->"Tahmine göre regle 1 gün kaldı.";else->"Tahmine göre regle $d gün kaldı."}}
private fun shortDate(d:LocalDate)=d.format(DateTimeFormatter.ofPattern("d MMM yyyy",Locale("tr","TR")))
private fun longDate(d:LocalDate)=d.format(DateTimeFormatter.ofPattern("d MMMM yyyy, EEEE",Locale("tr","TR"))).replaceFirstChar{it.uppercase(Locale("tr","TR"))}
